{
  "name": "USBlini USB-LIN总线接口",
  "name_en": "USBlini USB LIN Interface",
  "manufacturer": "",
  "description": "这是一种通过 USB 连接的 LIN 总线接口设备，用于在实验或测试系统中配置 LIN 通信速率、发送主站帧、设置从站帧表、编排主站轮询序列，并接收帧、状态和逻辑相关回调，适合 LIN 总线联调、协议测试与设备仿真。",
  "description_en": "This is a USB-connected LIN bus interface device used in lab or test setups to configure LIN communication speed, send master frames, define slave frame tables, schedule master sequences, and receive frame, status, and logic-related callbacks. It is suitable for LIN bus integration, protocol testing, and device emulation.",
  "actions": [
    {
      "action_name": "auto-open",
      "description": "打开与 USBlini 设备的连接。",
      "description_en": "Open the connection to the USBlini device."
    },
    {
      "action_name": "auto-close",
      "description": "关闭与 USBlini 设备的连接。",
      "description_en": "Close the connection to the USBlini device."
    },
    {
      "action_name": "auto-usbtransfer_ep1_callback",
      "description": "处理 USB 端点 1 的传输回调。",
      "description_en": "Handle the USB endpoint 1 transfer callback."
    },
    {
      "action_name": "auto-usbtransfer_ep2_callback",
      "description": "处理 USB 端点 2 的传输回调。",
      "description_en": "Handle the USB endpoint 2 transfer callback."
    },
    {
      "action_name": "auto-start_bootloader",
      "description": "使设备跳转到引导加载程序模式。",
      "description_en": "Jump the device into bootloader mode."
    },
    {
      "action_name": "auto-echo_test",
      "description": "执行回显测试以验证设备通信。",
      "description_en": "Run an echo test to verify device communication."
    },
    {
      "action_name": "auto-reset",
      "description": "复位设备，清除主站和从站表并恢复默认配置。",
      "description_en": "Reset the device, clear the master and slave tables, and restore the default configuration."
    },
    {
      "action_name": "auto-set_baudrate",
      "description": "设置 LIN 通信波特率，并可启用自动波特率功能。",
      "description_en": "Set the LIN communication baud rate, with optional autobaud support."
    },
    {
      "action_name": "auto-slave_set_frame",
      "description": "在从站表中设置一个 LIN 帧及其相关参数。",
      "description_en": "Define a LIN frame and its related parameters in the slave table."
    },
    {
      "action_name": "auto-master_write",
      "description": "以主站方式写入一个 LIN 帧并等待响应。",
      "description_en": "Write a LIN frame as master and wait for the response."
    },
    {
      "action_name": "auto-clear_errorflags",
      "description": "清除设备错误标志位。",
      "description_en": "Clear the device error flags."
    },
    {
      "action_name": "auto-master_set_sequence",
      "description": "设置主站帧序列及其周期和帧时隙时间。",
      "description_en": "Configure the master frame sequence, including its period and frame slot timing."
    },
    {
      "action_name": "auto-frame_listener_add",
      "description": "添加 LIN 帧监听回调函数。",
      "description_en": "Add a LIN frame listener callback."
    },
    {
      "action_name": "auto-frame_listener_remove",
      "description": "移除 LIN 帧监听回调函数。",
      "description_en": "Remove a LIN frame listener callback."
    },
    {
      "action_name": "auto-statusreport_listener_add",
      "description": "添加状态报告监听回调函数。",
      "description_en": "Add a status report listener callback."
    },
    {
      "action_name": "auto-statusreport_listener_remove",
      "description": "移除状态报告监听回调函数。",
      "description_en": "Remove a status report listener callback."
    },
    {
      "action_name": "auto-logic_listener_add",
      "description": "添加逻辑事件监听回调函数。",
      "description_en": "Add a logic-event listener callback."
    },
    {
      "action_name": "auto-logic_listener_remove",
      "description": "移除逻辑事件监听回调函数。",
      "description_en": "Remove a logic-event listener callback."
    }
  ],
  "tag_hints": [
    "LIN bus communication",
    "USB LIN interface",
    "automotive serial bus",
    "master/slave LIN emulation",
    "frame scheduling",
    "protocol testing",
    "firmware bootloader"
  ]
}

